import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Group,
  Color,
  Vector3,
  Matrix4,
  Quaternion,
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  tslFn,
  mix,
  float,
  vec3,
  uv,
  texture,
  color,
  normalWorld,
  positionWorld,
  reflectivity,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as createPrimitive } from '@/primitives';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const dock = new Group();
  dock.position.set(0, 0, 0);
  dock.rotation.set(0, 0, 0);
  dock.scale.set(1, 1, 1);
  dock.name = 'navigation-dock';

  // ---------- Rail ----------
  const railWidth = 3.6;
  const railHeight = 0.5;
  const railGeometry = new PlaneGeometry(railWidth, railHeight, 1, 1);
  const railMaterial = new MeshStandardNodeMaterial();

  // Gradient albedo via node
  const gradColor = tslFn(() => {
    const uvCoord = uv();
    const top = color('#1b1b23');
    const bottom = color('#101015');
    return mix(top, bottom, uvCoord.y);
  })();
  railMaterial.colorNode = gradColor;
  railMaterial.metalnessNode = float(0.5);
  railMaterial.roughnessNode = float(0.55);
  railMaterial.clearcoatNode = float(0.2);
  railMaterial.clearcoatRoughnessNode = float(0.1);
  railMaterial.anisotropyNode = float(0.6);
  railMaterial.anisotropyDirectionNode = vec3(1, 0, 0);
  railMaterial.side = 2; // DoubleSide

  const railMesh = new Mesh(railGeometry, railMaterial);
  railMesh.position.set(0, 0, 0.15);
  dock.add(railMesh);

  // ---------- Contact Shadow ----------
  const shadowPlane = new Mesh(
    new PlaneGeometry(railWidth, railHeight, 1, 1),
    new MeshBasicNodeMaterial({ color: 0x000000, transparent: true, opacity: 0.35 })
  );
  shadowPlane.position.set(0, -0.06, 0);
  dock.add(shadowPlane);

  // ---------- Navigation Items ----------
  const entries = [
    { label: 'HOME', active: true },
    { label: 'FEATURES', active: false },
    { label: 'COLLECTION', active: false },
    { label: 'PRICING', active: false },
    { label: 'JOURNAL', active: false },
  ];

  const entryGroup = new Group();
  entryGroup.name = 'entries';
  dock.add(entryGroup);

  const itemSpacing = 0.68;
  const startX = -((entries.length - 1) * itemSpacing) / 2;
  const itemWidth = 0.6;
  const itemHeight = 0.34;
  const baseFontSize = 0.13; // scene units approximating 13px at body scale

  const hoverColor = new Color('#e8ecf2');
  const inactiveColor = new Color('#a6adba');
  const activeColor = new Color('#e8ecf2');
  const accentColor = new Color('#ff2a38');

  const timelines = [];

  // Underline bar
  const underlineGeometry = new PlaneGeometry(0.28, 0.025);
  const underlineMaterial = new MeshBasicNodeMaterial({ color: accentColor, transparent: true, opacity: 1 });
  const underlineMesh = new Mesh(underlineGeometry, underlineMaterial);
  underlineMesh.position.set(startX, -0.06, 0.01);
  dock.add(underlineMesh);

  let activeIndex = 0;

  entries.forEach((entry, i) => {
    const container = new Group();
    container.name = entry.label.toLowerCase();
    container.position.set(startX + i * itemSpacing, 0, 0);
    entryGroup.add(container);

    // Text mesh
    const txtColor = entry.active ? activeColor : inactiveColor;
    const textMesh = createTextMesh(entry.label, {
      fontFamily: 'JetBrains Mono',
      fontWeight: entry.active ? 700 : 400,
      fontSize: baseFontSize,
      color: txtColor.getStyle(),
      align: 'center',
      atlas: ctx.fontAtlas,
      atlasRegion: { atlas: 0, x: 0, y: 0, w: 512, h: 320 },
    });
    textMesh.position.set(0, 0, 0.02);
    container.add(textMesh);

    // Hit area (transparent)
    const hitGeometry = new PlaneGeometry(itemWidth, itemHeight);
    const hitMaterial = new MeshBasicNodeMaterial({ transparent: true, opacity: 0 });
    const hitMesh = new Mesh(hitGeometry, hitMaterial);
    hitMesh.position.set(0, 0, 0);
    container.add(hitMesh);

    // Store references for animation
    const entryObj = {
      container,
      textMesh,
      hitMesh,
      index: i,
      active: entry.active,
      txtMaterial: textMesh.material,
    };

    // ---------- Handlers ----------
    const handlers = {};

    // Hover enter
    handlers.pointerenter = () => {
      if (entryObj.active) return;
      const tl = gsap.to(entryObj.txtMaterial.color, {
        r: hoverColor.r,
        g: hoverColor.g,
        b: hoverColor.b,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      timelines.push(tl);
    };

    // Hover leave
    handlers.pointerleave = () => {
      if (entryObj.active) return;
      const tl = gsap.to(entryObj.txtMaterial.color, {
        r: inactiveColor.r,
        g: inactiveColor.g,
        b: inactiveColor.b,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      timelines.push(tl);
    };

    // Press down
    handlers.pointerdown = () => {
      const tl = gsap.to(entryObj.container.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      timelines.push(tl);
      // slight Z dip
      gsap.to(entryObj.container.position, {
        z: -0.03,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
    };

    // Release press / activate
    handlers.pointerup = () => {
      const tl = gsap.to(entryObj.container.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      timelines.push(tl);
      gsap.to(entryObj.container.position, {
        z: 0,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });

      // Activate this entry if not already active
      if (!entryObj.active) {
        const prevActive = entries[activeIndex];
        const prevObj = entryGroup.children[activeIndex].userData.entryObj;

        // Update colors
        gsap.to(prevObj.txtMaterial.color, {
          r: inactiveColor.r,
          g: inactiveColor.g,
          b: inactiveColor.b,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        gsap.to(entryObj.txtMaterial.color, {
          r: activeColor.r,
          g: activeColor.g,
          b: activeColor.b,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });

        // Move underline
        const targetX = entryObj.container.position.x;
        gsap.to(underlineMesh.position, {
          x: targetX,
          duration: 0.26,
          ease: 'cubic-bezier(0.165,0.84,0.44,1)',
          onComplete: () => {
            // overshoot weighted settle
            gsap.to(underlineMesh.position, {
              x: targetX,
              duration: 0.9,
              ease: 'power4.out',
            });
          },
        });

        // Update active flags
        prevObj.active = false;
        entryObj.active = true;
        activeIndex = entryObj.index;

        // Dispatch navigation event if context provides handler
        if (ctx.handlers && typeof ctx.handlers.navigate === 'function') {
          ctx.handlers.navigate(entry.label.toLowerCase());
        }
      }
    };

    // Attach handlers to userData
    container.userData.handlers = handlers;
    container.userData.entryObj = entryObj;
  });

  // ---------- Mount Animation ----------
  dock.position.y += 0.4;
  gsap.to(dock.position, {
    y: 0,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });

  // ---------- Cleanup ----------
  dock.userData.cleanup = () => {
    // Dispose geometries and materials
    railGeometry.dispose();
    railMaterial.dispose();
    shadowPlane.geometry.dispose();
    shadowPlane.material.dispose();
    underlineGeometry.dispose();
    underlineMaterial.dispose();

    entryGroup.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material && child.material.dispose) child.material.dispose();
      }
    });

    // Kill GSAP timelines
    timelines.forEach((tl) => {
      if (tl && tl.kill) tl.kill();
    });
    gsap.killTweensOf(dock.position);
    gsap.killTweensOf(underlineMesh.position);
  };

  return dock;
}
